def transform(grid):
    pts=[(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x!=7]
    rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
    r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
    tile=[row[c0:c1+1] for row in grid[r0:r1+1]]
    h,w=len(tile),len(tile[0])
    dx=2 if h==3 and w==3 and tile[0][1]==7 and tile[2][1]==7 else 0
    dy=2 if h==3 and w==3 and tile[1][0]==7 and tile[1][2]==7 else 0
    out=[[0]*16 for _ in range(16)]
    for r in range(4):
        for c in range(4):
            for dr in (1,2):
                for dc in (1,2): out[4*r+dr][4*c+dc]=7
    if dx:
        out=[row[dx:]+row[:dx] for row in out]
    if dy:
        out=out[dy:]+out[:dy]
    for r in range(h):
        for c in range(w):
            x=7 if tile[r][c]==7 else 9
            for dr in (1,2):
                for dc in (1,2): out[4*(r+1)+dr][4*(c+1)+dc]=x
    # Connect orthogonally adjacent maroon cells.
    for r in range(h):
        for c in range(w):
            if tile[r][c]==7: continue
            if c+1<w and tile[r][c+1]!=7:
                for dr in (1,2): out[4*(r+1)+dr][4*(c+1)+3]=9
            if r+1<h and tile[r+1][c]!=7:
                for dc in (1,2): out[4*(r+1)+3][4*(c+1)+dc]=9
    return out
